    """Audit Claude Code skills ecosystem (separate from Hermes)"""
    if not CLAUDE_SKILLS_DIR.exists():
        return {"metric": "Claude Code 技能生态", "value": "目录不存在", "status": "SKIP"}

    skills = list(CLAUDE_SKILLS_DIR.iterdir())
    total = len(skills)
    has_tests = sum(1 for s in skills if (s / "test-prompts.json").exists())
    has_changelog = sum(1 for s in skills if (s / "CHANGELOG.md").exists())
    has_sk = sum(1 for s in skills if (s / "SKILL.md").exists())

    # Find overlap with Hermes
    hermes_names = {s.parent.name for s in SKILLS_DIR.rglob("SKILL.md")}
    claude_names = {s.name for s in skills if (s / "SKILL.md").exists()}
    overlap = hermes_names & claude_names

    return {
        "metric": "Claude Code 技能生态",
        "value": f"{total} skills ({has_sk} with SKILL.md)",
        "test_coverage": f"{has_tests}/{total}",
        "changelog_coverage": f"{has_changelog}/{total}",
        "overlap_with_hermes": len(overlap),
        "overlap_names": list(overlap)[:10],
        "status": "OK" if has_sk > 0 else "NO_SKILLS",
    }

